type stagedSave struct {
	ex     *Execution
	events []OutboxEvent
}

// memoryTx 是 MemoryStore 的事务：所有修改暂存于私有副本，Commit 时
// 在单一互斥锁下完成冲突检查与应用，因此状态保存与事件追加是原子的。
