// Package saga 提供可嵌入应用的 Saga 编排引擎：顺序正向步骤、失败逆序补偿、
// 执行幂等以及基于 Outbox 的事件投递。
//
// 执行身份由业务键（BusinessKey）、Saga 定义（Definition）与外部幂等键
// （IdempotencyKey）共同确定。调用方为每个正向步骤提供遵守幂等契约的动作，
// 为可能成功的步骤提供补偿动作。引擎只依赖 Go 标准库；状态如何落盘由
// Store 实现决定，本包不规定任何磁盘文件格式。
package saga

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"strings"
)

// Sentinel errors returned by the engine and stores.
var (
	// ErrInvalidDefinition 表示 Saga 定义非法，或执行请求缺失幂等键/业务键。
	ErrInvalidDefinition = errors.New("saga: invalid definition")

	// ErrDefinitionConflict 表示相同业务键已绑定另一个 Saga 定义。
	ErrDefinitionConflict = errors.New("saga: definition conflict for business key")

	// ErrExecutionNotFound 表示执行身份（业务键 + 幂等键）不存在。
	ErrExecutionNotFound = errors.New("saga: execution not found")

	// ErrAlreadyClaimed 表示 Outbox 事件已被其他领取者占用（乐观并发）。
	ErrAlreadyClaimed = errors.New("saga: outbox event already claimed")

	// ErrConcurrentUpdate 表示执行记录已被其他事务推进（乐观锁冲突）。
	ErrConcurrentUpdate = errors.New("saga: concurrent execution update")

	// ErrExecutionAlreadyExists 表示执行身份在创建时已存在（并发重试）。
	ErrExecutionAlreadyExists = errors.New("saga: execution already exists")

	// ErrEventNotFound 表示 Outbox 事件不存在。
	ErrEventNotFound = errors.New("saga: outbox event not found")
)

// ExecutionState 是一次执行在某时刻的确定状态。
type ExecutionState string

const (
	// StateRunning 正向步骤仍在推进，尚未进入终态。
	StateRunning ExecutionState = "running"
	// StateCompleted 所有正向步骤均已确认成功。
	StateCompleted ExecutionState = "completed"
	// StateFailed 某正向步骤失败，且此前成功步骤均已补偿完成。
	StateFailed ExecutionState = "failed"
	// StateCompensationFailed 补偿过程中出现错误，终态被冻结。
	StateCompensationFailed ExecutionState = "compensation_failed"
)

// Terminal 报告状态是否为终态。终态结果一经形成不再改变。
func (s ExecutionState) Terminal() bool {
	switch s {
	case StateCompleted, StateFailed, StateCompensationFailed:
		return true
	default:
		return false
	}
}

// StepState 是单个步骤的处理状态。
type StepState string

const (
	// StepPending 步骤尚未开始。
	StepPending StepState = "pending"
	// StepSucceeded 正向动作已成功并确认提交。
	StepSucceeded StepState = "succeeded"
	// StepFailed 正向动作返回错误（该步未确认成功，不会被补偿）。
	StepFailed StepState = "failed"
	// StepCompensated 该步的补偿动作已成功确认。
	StepCompensated StepState = "compensated"
	// StepCompensationFailed 该步的补偿动作返回错误。
	StepCompensationFailed StepState = "compensation_failed"
)

// Action 执行一个正向步骤。
//
// 动作必须遵守幂等契约：网络抖动、进程重启等未确认场景下引擎可能以相同
// 输入再次调用同一动作，动作自身需保证重复调用与单次调用等价。
type Action func(ctx context.Context) error

// Compensation 执行一个已成功步骤的补偿动作，同样需满足幂等契约。
// 参数为对应正向动作返回的错误（补偿正常路径下为 nil），保留以便补偿逻辑
// 感知上下文；多数实现可忽略。
type Compensation func(ctx context.Context) error

// Step 定义 Saga 中的一个正向步骤及其补偿。
type Step struct {
	// Name 是步骤在其所属 Definition 内的唯一名称。
	Name string
	// Do 为正向动作，必填。
	Do Action
	// Compensate 为补偿动作；无需补偿的步骤可留空，补偿时视为成功。
	Compensate Compensation
}

// Definition 是一个具名 Saga 的步骤编排定义。
type Definition struct {
	// Name 为 Saga 类型名，用于诊断，不参与执行身份判定。
	Name string
	// Steps 按正向执行顺序排列；补偿按相反顺序执行。
	Steps []Step
}

// fingerprint 返回定义内容的稳定指纹：相同的步骤名序列产生相同指纹。
// 动作是代码而非数据，不纳入指纹；执行身份由调用方通过 Definition 的
// 步骤结构与名称保证一致性。
func (d Definition) fingerprint() string {
	h := sha256.New()
	h.Write([]byte(d.Name))
	h.Write([]byte{0})
	for _, s := range d.Steps {
		h.Write([]byte(s.Name))
		h.Write([]byte{0})
	}
	sum := h.Sum(nil)
	return hex.EncodeToString(sum[:12])
}

// validate 校验定义与请求的基本不变量。
func (d Definition) validate() error {
	if len(d.Steps) == 0 {
		return ErrInvalidDefinition
	}
	seen := make(map[string]struct{}, len(d.Steps))
	for _, s := range d.Steps {
		if strings.TrimSpace(s.Name) == "" {
			return ErrInvalidDefinition
		}
		if s.Do == nil {
			return ErrInvalidDefinition
		}
		if _, dup := seen[s.Name]; dup {
			return ErrInvalidDefinition
		}
		seen[s.Name] = struct{}{}
	}
	return nil
}

// Request 是一次 Saga 执行请求。
type Request struct {
	// BusinessKey 是调用方的唯一业务键，同一业务键绑定同一 Saga 定义。
	BusinessKey string
	// IdempotencyKey 是本次执行的外部幂等键；与 BusinessKey、定义共同
	// 确定执行身份。缺失时返回 ErrInvalidDefinition。
	IdempotencyKey string
}

func (r Request) validate() error {
	if strings.TrimSpace(r.BusinessKey) == "" {
		return ErrInvalidDefinition
	}
	if strings.TrimSpace(r.IdempotencyKey) == "" {
		return ErrInvalidDefinition
	}
	return nil
}

// StepResult 是单个步骤的处理结果，按步骤定义顺序返回。
type StepResult struct {
	// Name 为步骤名。
	Name string
	// State 为该步当前状态。
	State StepState
	// Attempts 为正向动作被实际调用的次数（用于调用方判断是否发生重复处理）。
	Attempts int
	// Error 为最近一次失败的错误描述；成功时为空。
	Error string
}

// Result 是一次执行的确定结果。终态结果在后续调用中原样返回。
type Result struct {
	// BusinessKey 为业务键。
	BusinessKey string
	// IdempotencyKey 为外部幂等键。
	IdempotencyKey string
	// Saga 为 Saga 定义名。
	Saga string
	// State 为执行状态。
	State ExecutionState
	// FailureReason 为导致失败/补偿失败的原因；成功时为空。
	FailureReason string
	// Steps 为各步骤的处理结果，顺序与定义一致。
	Steps []StepResult
}

package saga

import (
	"context"
	"encoding/json"
	"fmt"
	"time"
)

// Engine 按 Saga 定义顺序执行正向步骤、在失败时逆序补偿，并把每次状态
// 变化以 Outbox 事件原子写入 Store。Engine 可并发使用；同一执行身份的
// 并发调用通过乐观锁收敛为一次实际推进。
type Engine struct {
	store Store
	now   func() time.Time
}

// NewEngine 创建基于 store 的编排引擎。
func NewEngine(store Store) *Engine {
	return &Engine{store: store, now: time.Now}
}

// optimisticRounds 限制单个动作在乐观锁冲突下的重读轮数。
const optimisticRounds = 100

// Execute 按请求执行（或恢复）一次 Saga 执行，返回其确定结果。
//
// 执行身份由业务键、Saga 定义与外部幂等键共同确定：
//   - 定义非法或缺少业务键/幂等键：ErrInvalidDefinition；
//   - 相同业务键已绑定不同定义：ErrDefinitionConflict；
//   - 同身份重试：不重复执行已确认成功的正向或补偿步骤，未确认结果的
//     步骤可能被再次调用（动作须自身幂等）；
//   - 终态（completed/failed/compensation_failed）一经形成不再改变，
//     后续调用直接返回同一结果。
func (e *Engine) Execute(ctx context.Context, def Definition, req Request) (Result, error) {
	if err := def.validate(); err != nil {
		return Result{}, err
	}
	if err := req.validate(); err != nil {
		return Result{}, err
	}
	hash := def.fingerprint()

	// 确保执行已登记（execution.started 事件随创建原子落盘）。
	ex, err := e.ensureExecution(ctx, def, req, hash)
	if err != nil {
		return Result{}, err
	}
	if ex.State.Terminal() {
		return buildResult(ex), nil
	}

	// 推进循环：每轮“读快照 → 决定下一步 → 在锁外执行动作 → 重读提交”，
	// 提交遇乐观锁冲突则整轮重读。每步确认单独提交后才会进入下一步。
	for round := 0; round < optimisticRounds; round++ {
		if err := ctx.Err(); err != nil {
			return Result{}, err
		}

		tx, err := e.store.Begin(ctx)
		if err != nil {
			return Result{}, err
		}
		ex, err = tx.LoadExecution(req.BusinessKey, req.IdempotencyKey)
		if err != nil {
			tx.Rollback()
			return Result{}, err
		}
		tx.Rollback()

		if ex.State.Terminal() {
			return buildResult(ex), nil
		}

		work := nextWork(ex)
		if work.kind == workDone {
			return buildResult(ex), nil
		}

		// 在任何存储锁之外执行业务动作。
		var actionErr error
		switch work.kind {
		case workForward:
			actionErr = def.Steps[work.index].Do(ctx)
		case workCompensate:
			comp := def.Steps[work.index].Compensate
			if comp == nil {
				actionErr = nil // 无需补偿的步骤按补偿成功处理
			} else {
				actionErr = comp(ctx)
			}
		}

		committed, err := e.commitStep(ctx, req, work, actionErr)
		if err != nil {
			return Result{}, err
		}
		if !committed {
			// 状态已被并发调用推进，重读后再决策。
			continue
		}
	}
	return Result{}, fmt.Errorf("saga: execution %s/%s did not converge after %d rounds", req.BusinessKey, req.IdempotencyKey, optimisticRounds)
}

// GetResult 返回既有执行的当前结果。未知执行身份返回 ErrExecutionNotFound。
func (e *Engine) GetResult(ctx context.Context, businessKey, idempotencyKey string) (Result, error) {
	tx, err := e.store.Begin(ctx)
	if err != nil {
		return Result{}, err
	}
	ex, err := tx.LoadExecution(businessKey, idempotencyKey)
	tx.Rollback()
	if err != nil {
		return Result{}, err
	}
	return buildResult(ex), nil
}

// ensureExecution 加载既有执行；不存在则原子创建（含 started 事件）。
// 并发创建冲突时转为加载既有执行。
func (e *Engine) ensureExecution(ctx context.Context, def Definition, req Request, hash string) (*Execution, error) {
	for {
		tx, err := e.store.Begin(ctx)
		if err != nil {
			return nil, err
		}
		ex, loadErr := tx.LoadExecution(req.BusinessKey, req.IdempotencyKey)
		if loadErr == nil {
			tx.Rollback()
			if ex.DefinitionHash != hash {
				return nil, ErrDefinitionConflict
			}
			return ex, nil
		}
		if loadErr != ErrExecutionNotFound {
			tx.Rollback()
			return nil, loadErr
		}
		tx.Rollback()

		now := e.now().UTC()
		created := &Execution{
			BusinessKey:    req.BusinessKey,
			IdempotencyKey: req.IdempotencyKey,
			SagaName:       def.Name,
			DefinitionHash: hash,
			State:          StateRunning,
			Steps:          make([]StepRecord, len(def.Steps)),
			StartedAt:      now,
			UpdatedAt:      now,
		}
		for i, s := range def.Steps {
			created.Steps[i] = StepRecord{Name: s.Name, State: StepPending}
		}
		startedEvent := e.newEvent(created, EventExecutionStarted, EventPayload{State: StateRunning})

		createTx, err := e.store.Begin(ctx)
		if err != nil {
			return nil, err
		}
		if err := createTx.CreateExecution(created); err != nil {
			createTx.Rollback()
			return nil, err
		}
		if err := createTx.SaveExecution(created, []OutboxEvent{startedEvent}); err != nil {
			createTx.Rollback()
			return nil, err
		}
		switch err := createTx.Commit(); {
		case err == nil:
			return created, nil
		case err == ErrExecutionAlreadyExists:
			// 并发调用抢先创建：重读其结果。
			continue
		default:
			return nil, err
		}
	}
}

type workKind int

const (
	workDone workKind = iota
	workForward
	workCompensate
)

type nextStep struct {
	kind  workKind
	index int
}

// nextWork 依据持久化状态决定下一步：
//   - 尚无失败步骤：推进第一个 pending 正向步骤；全部成功则收敛为 completed；
//   - 已出现失败步骤：逆序选取第一个 succeeded 步骤进行补偿；全部处理完
//     则收敛为 failed。
func nextWork(ex *Execution) nextStep {
	compensating := false
	for i := range ex.Steps {
		if ex.Steps[i].State == StepFailed ||
			ex.Steps[i].State == StepCompensationFailed {
			compensating = true
			break
		}
	}

	if !compensating {
		for i := range ex.Steps {
			if ex.Steps[i].State == StepPending {
				return nextStep{kind: workForward, index: i}
			}
		}
		return nextStep{kind: workDone}
	}

	for i := len(ex.Steps) - 1; i >= 0; i-- {
		if ex.Steps[i].State == StepSucceeded {
			return nextStep{kind: workCompensate, index: i}
		}
	}
	return nextStep{kind: workDone}
}

// commitStep 重读执行、确认目标步骤仍是预期状态后提交该步结果；返回
// committed=false 表示已被并发调用推进，调用方应重读决策。
func (e *Engine) commitStep(ctx context.Context, req Request, work nextStep, actionErr error) (bool, error) {
	tx, err := e.store.Begin(ctx)
	if err != nil {
		return false, err
	}
	defer tx.Rollback()

	ex, err := tx.LoadExecution(req.BusinessKey, req.IdempotencyKey)
	if err != nil {
		return false, err
	}
	if ex.State.Terminal() {
		return true, nil // 终态已由并发调用形成，无需再写。
	}

	var events []OutboxEvent
	now := e.now().UTC()

	switch work.kind {
	case workForward:
		step := &ex.Steps[work.index]
		if step.State != StepPending {
			return false, nil // 已被确认（成功或失败），重读决策。
		}
		step.Attempts++
		if actionErr != nil {
			step.State = StepFailed
			step.LastError = actionErr.Error()
			events = append(events, e.newEvent(ex, EventStepFailed, EventPayload{
				Step: step.Name, State: ex.State, Reason: step.LastError, Attempts: step.Attempts,
			}))
			break
		}
		step.State = StepSucceeded
		step.LastError = ""
		events = append(events, e.newEvent(ex, EventStepSucceeded, EventPayload{
			Step: step.Name, State: ex.State, Attempts: step.Attempts,
		}))
		// 正向全部确认：形成 completed 终态。
		if allSucceeded(ex.Steps) {
			ex.State = StateCompleted
			events = append(events, e.newEvent(ex, EventExecutionCompleted, EventPayload{
				State: StateCompleted,
			}))
		}

	case workCompensate:
		step := &ex.Steps[work.index]
		if step.State != StepSucceeded {
			return false, nil // 补偿已被确认或执行已冻结，重读决策。
		}
		if actionErr != nil {
			step.State = StepCompensationFailed
			step.LastError = actionErr.Error()
			ex.State = StateCompensationFailed
			ex.FailureReason = fmt.Sprintf("compensation of step %q failed: %s", step.Name, actionErr.Error())
			events = append(events, e.newEvent(ex, EventCompensationFailed, EventPayload{
				Step: step.Name, State: StateCompensationFailed, Reason: ex.FailureReason,
			}))
			break
		}
		step.CompensationAttempts++
		step.State = StepCompensated
		step.LastError = ""
		events = append(events, e.newEvent(ex, EventStepCompensated, EventPayload{
			Step: step.Name, State: ex.State, Attempts: step.CompensationAttempts,
		}))
		// 逆序补偿全部完成：形成 failed 终态。
		if !anySucceeded(ex.Steps) {
			ex.State = StateFailed
			ex.FailureReason = forwardFailureReason(ex.Steps)
			events = append(events, e.newEvent(ex, EventExecutionFailed, EventPayload{
				State: StateFailed, Reason: ex.FailureReason,
			}))
		}
	}

	_ = now
	if err := tx.SaveExecution(ex, events); err != nil {
		return false, err
	}
	if err := tx.Commit(); err != nil {
		if err == ErrConcurrentUpdate {
			return false, nil
		}
		return false, err
	}
	return true, nil
}

// newEvent 追加一条事件：序号前移、ID 按执行身份与序号确定性生成。
func (e *Engine) newEvent(ex *Execution, typ EventType, p EventPayload) OutboxEvent {
	ex.EventSeq++
	payload, _ := json.Marshal(p)
	return OutboxEvent{
		ID:             fmt.Sprintf("%s:%s:%06d", ex.BusinessKey, ex.IdempotencyKey, ex.EventSeq),
		BusinessKey:    ex.BusinessKey,
		IdempotencyKey: ex.IdempotencyKey,
		Type:           typ,
		OccurredAt:     e.now().UTC(),
		Payload:        payload,
	}
}

func allSucceeded(steps []StepRecord) bool {
	for i := range steps {
		if steps[i].State != StepSucceeded {
			return false
		}
	}
	return true
}

func anySucceeded(steps []StepRecord) bool {
	for i := range steps {
		if steps[i].State == StepSucceeded {
			return true
		}
	}
	return false
}

func forwardFailureReason(steps []StepRecord) string {
	for i := range steps {
		if steps[i].State == StepFailed {
			return fmt.Sprintf("step %q failed: %s", steps[i].Name, steps[i].LastError)
		}
	}
	return ""
}

func buildResult(ex *Execution) Result {
	r := Result{
		BusinessKey:    ex.BusinessKey,
		IdempotencyKey: ex.IdempotencyKey,
		Saga:           ex.SagaName,
		State:          ex.State,
		FailureReason:  ex.FailureReason,
		Steps:          make([]StepResult, len(ex.Steps)),
	}
	for i, s := range ex.Steps {
		r.Steps[i] = StepResult{
			Name:     s.Name,
			State:    s.State,
			Attempts: s.Attempts,
			Error:    s.LastError,
		}
	}
	if r.State == StateFailed && r.FailureReason == "" {
		r.FailureReason = forwardFailureReason(ex.Steps)
	}
	return r
}

