func TestOutboxFailureKeepsEventAndIncrementsAttempts(t *testing.T) {
	ctx := context.Background()
	s := newScript()
	store := saga.NewMemoryStore()
	engine := saga.NewEngine(store)
	if _, err := engine.Execute(ctx, threeStepDef(s), saga.Request{BusinessKey: "bk-6", IdempotencyKey: "idem-6"}); err != nil {
		t.Fatalf("execute: %v", err)
	}

	// 首轮发送失败：事件保留、计数加一、立即可再次领取。
	bad := &failAlwaysPub{}
	n, err := saga.DeliverPending(ctx, store, bad, 10, time.Minute)
	if err == nil || n != 0 {
		t.Fatalf("deliver = (%d, %v), want 0 with error", n, err)
	}
	firstCount := bad.n
	if firstCount == 0 {
		t.Fatalf("publisher never invoked")
	}

	evs, err := store.ClaimEvents(ctx, 10, time.Minute)
	if err != nil {
		t.Fatalf("reclaim: %v", err)
	}
	if len(evs) != firstCount {
		t.Fatalf("reclaimed %d events, want %d", len(evs), firstCount)
	}
	for _, ev := range evs {
		if ev.Attempts != 1 || ev.LastError == "" {
			t.Fatalf("event %s attempts=%d err=%q, want 1 with reason", ev.ID, ev.Attempts, ev.LastError)
		}
	}

	// 恢复后发送成功并标记，不再被领取。
	var delivered []string
	ok := pubFunc(func(_ context.Context, ev saga.OutboxEvent) error {
		delivered = append(delivered, ev.ID)
		return nil
	})
	n, err = saga.DeliverPending(ctx, store, ok, 10, time.Minute)
	if err != nil || n != firstCount {
		t.Fatalf("redeliver = (%d, %v), want %d nil", n, err, firstCount)
	}
	if more, _ := store.ClaimEvents(ctx, 10, time.Minute); len(more) != 0 {
		t.Fatalf("marked events still claimable: %d", len(more))
	}
}

