1	package saga
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"sync"
8		"time"
9	)
10	
11	// Engine 按 Saga 定义顺序执行正向步骤、在失败时逆序补偿，并把每次状态
12	// 变化以 Outbox 事件原子写入 Store。Engine 可并发使用；同一执行身份的
13	// 并发调用在本引擎内串行推进（动作不会因并发而重复调用），跨进程并发
14	// 则通过乐观锁收敛，未确认结果的重新调用由动作的幂等契约兜底。
15	type Engine struct {
16		store Store
17		now   func() time.Time
18	
19		keyMu    sync.Mutex
20		keyLocks map[string]*keyedLock
21	}
22	
23	// NewEngine 创建基于 store 的编排引擎。
24	func NewEngine(store Store) *Engine {
25		return &Engine{store: store, now: time.Now, keyLocks: make(map[string]*keyedLock)}
26	}
27	
28	// keyedLock 是一个执行身份的串行锁及其引用计数。
29	type keyedLock struct {
30		mu   sync.Mutex
31		refs int
32	}
33	
34	// lockKey 获取同一执行身份的串行锁，返回释放函数。
35	func (e *Engine) lockKey(businessKey, idempotencyKey string) func() {
36		key := executionKey(businessKey, idempotencyKey)
37		e.keyMu.Lock()
38		kl, ok := e.keyLocks[key]
39		if !ok {
40			kl = &keyedLock{}
41			e.keyLocks[key] = kl
42		}
43		kl.refs++
44		e.keyMu.Unlock()
45	
46		kl.mu.Lock()
47		return func() {
48			kl.mu.Unlock()
49			e.keyMu.Lock()
50			kl.refs--
51			if kl.refs == 0 {
52				delete(e.keyLocks, key)
53			}
54			e.keyMu.Unlock()
55		}
56	}
57	
58	// optimisticRounds 限制单个动作在乐观锁冲突下的重读轮数。
59	const optimisticRounds = 100
60	
61	// Execute 按请求执行（或恢复）一次 Saga 执行，返回其确定结果。
62	//
63	// 执行身份由业务键、Saga 定义与外部幂等键共同确定：
64	//   - 定义非法或缺少业务键/幂等键：ErrInvalidDefinition；
65	//   - 相同业务键已绑定不同定义：ErrDefinitionConflict；
66	//   - 同身份重试：不重复执行已确认成功的正向或补偿步骤，未确认结果的
67	//     步骤可能被再次调用（动作须自身幂等）；
68	//   - 终态（completed/failed/compensation_failed）一经形成不再改变，
69	//     后续调用直接返回同一结果。
70	func (e *Engine) Execute(ctx context.Context, def Definition, req Request) (Result, error) {
71		if err := def.validate(); err != nil {
72			return Result{}, err
73		}
74		if err := req.validate(); err != nil {
75			return Result{}, err
76		}
77		hash := def.fingerprint()
78	
79		// 同一执行身份在本引擎内串行：避免并发请求对同一未确认步骤重复调用动作。
80		unlock := e.lockKey(req.BusinessKey, req.IdempotencyKey)
81		defer unlock()
82	
83		// 确保执行已登记（execution.started 事件随创建原子落盘）。
84		ex, err := e.ensureExecution(ctx, def, req, hash)
85		if err != nil {
86			return Result{}, err
87		}
88		if ex.State.Terminal() {
89			return buildResult(ex), nil
90		}
91	
92		// 推进循环：每轮“读快照 → 决定下一步 → 在锁外执行动作 → 重读提交”，
93		// 提交遇乐观锁冲突则整轮重读。每步确认单独提交后才会进入下一步。
94		for round := 0; round < optimisticRounds; round++ {
95			if err := ctx.Err(); err != nil {
96				return Result{}, err
97			}
98	
99			tx, err := e.store.Begin(ctx)
100			if err != nil {
101				return Result{}, err
102			}
103			ex, err = tx.LoadExecution(req.BusinessKey, req.IdempotencyKey)
104			if err != nil {
105				tx.Rollback()
106				return Result{}, err
107			}
108			tx.Rollback()
109	
110			if ex.State.Terminal() {
111				return buildResult(ex), nil
112			}
113	
114			work := nextWork(ex)
115			if work.kind == workDone {
116				return buildResult(ex), nil
117			}
118	
119			// 在任何存储锁之外执行业务动作。
120			var actionErr error
121			switch work.kind {
122			case workForward:
123				actionErr = def.Steps[work.index].Do(ctx)
124			case workCompensate:
125				comp := def.Steps[work.index].Compensate
126				if comp == nil {
127					actionErr = nil // 无需补偿的步骤按补偿成功处理
128				} else {
129					actionErr = comp(ctx)
130				}
131			}
132	
133			committed, err := e.commitStep(ctx, def, req, work, actionErr)
134			if err != nil {
135				return Result{}, err
136			}
137			if !committed {
138				// 状态已被并发调用推进，重读后再决策。
139				continue
140			}
141		}
142		return Result{}, fmt.Errorf("saga: execution %s/%s did not converge after %d rounds", req.BusinessKey, req.IdempotencyKey, optimisticRounds)
143	}
144	
145	// GetResult 返回既有执行的当前结果。未知执行身份返回 ErrExecutionNotFound。
146	func (e *Engine) GetResult(ctx context.Context, businessKey, idempotencyKey string) (Result, error) {
147		tx, err := e.store.Begin(ctx)
148		if err != nil {
149			return Result{}, err
150		}
151		ex, err := tx.LoadExecution(businessKey, idempotencyKey)
152		tx.Rollback()
153		if err != nil {
154			return Result{}, err
155		}
156		return buildResult(ex), nil
157	}
158	
159	// ensureExecution 加载既有执行；不存在则原子创建（含 started 事件）。
160	// 并发创建冲突时转为加载既有执行。
161	func (e *Engine) ensureExecution(ctx context.Context, def Definition, req Request, hash string) (*Execution, error) {
162		for {
163			tx, err := e.store.Begin(ctx)
164			if err != nil {
165				return nil, err
166			}
167			ex, loadErr := tx.LoadExecution(req.BusinessKey, req.IdempotencyKey)
168			if loadErr == nil {
169				tx.Rollback()
170				if ex.DefinitionHash != hash {
171					return nil, ErrDefinitionConflict
172				}
173				return ex, nil
174			}
175			if loadErr != ErrExecutionNotFound {
176				tx.Rollback()
177				return nil, loadErr
178			}
179			tx.Rollback()
180	
181			now := e.now().UTC()
182			created := &Execution{
183				BusinessKey:    req.BusinessKey,
184				IdempotencyKey: req.IdempotencyKey,
185				SagaName:       def.Name,
186				DefinitionHash: hash,
187				State:          StateRunning,
188				Steps:          make([]StepRecord, len(def.Steps)),
189				StartedAt:      now,
190				UpdatedAt:      now,
191			}
192			for i, s := range def.Steps {
193				created.Steps[i] = StepRecord{Name: s.Name, State: StepPending}
194			}
195			startedEvent := e.newEvent(created, EventExecutionStarted, EventPayload{State: StateRunning})
196	
197			createTx, err := e.store.Begin(ctx)
198			if err != nil {
199				return nil, err
200			}
201			if err := createTx.CreateExecution(created); err != nil {
202				createTx.Rollback()
203				return nil, err
204			}
205			if err := createTx.SaveExecution(created, []OutboxEvent{startedEvent}); err != nil {
206				createTx.Rollback()
207				return nil, err
208			}
209			switch err := createTx.Commit(); {
210			case err == nil:
211				return created, nil
212			case err == ErrExecutionAlreadyExists:
213				// 并发调用抢先创建：重读其结果。
214				continue
215			default:
216				return nil, err
217			}
218		}
219	}
220	
221	type workKind int
222	
223	const (
224		workDone workKind = iota
225		workForward
226		workCompensate
227	)
228	
229	type nextStep struct {
230		kind  workKind
231		index int
232	}
233	
234	// nextWork 依据持久化状态决定下一步：
235	//   - 尚无失败步骤：推进第一个 pending 正向步骤；全部成功则收敛为 completed；
236	//   - 已出现失败步骤：逆序选取第一个 succeeded 步骤进行补偿；全部处理完
237	//     则收敛为 failed。
238	func nextWork(ex *Execution) nextStep {
239		compensating := false
240		for i := range ex.Steps {
241			if ex.Steps[i].State == StepFailed ||
242				ex.Steps[i].State == StepCompensationFailed {
243				compensating = true
244				break
245			}
246		}
247	
248		if !compensating {
249			for i := range ex.Steps {
250				if ex.Steps[i].State == StepPending {
251					return nextStep{kind: workForward, index: i}
252				}
253			}
254			return nextStep{kind: workDone}
255		}
256	
257		for i := len(ex.Steps) - 1; i >= 0; i-- {
258			if ex.Steps[i].State == StepSucceeded {
259				return nextStep{kind: workCompensate, index: i}
260			}
261		}
262		return nextStep{kind: workDone}
263	}
264	
265	// commitStep 重读执行、确认目标步骤仍是预期状态后提交该步结果；返回
266	// committed=false 表示已被并发调用推进，调用方应重读决策。
267	func (e *Engine) commitStep(ctx context.Context, def Definition, req Request, work nextStep, actionErr error) (bool, error) {
268		tx, err := e.store.Begin(ctx)
269		if err != nil {
270			return false, err
271		}
272		defer tx.Rollback()
273	
274		ex, err := tx.LoadExecution(req.BusinessKey, req.IdempotencyKey)
275		if err != nil {
276			return false, err
277		}
278		if ex.State.Terminal() {
279			return true, nil // 终态已由并发调用形成，无需再写。
280		}
281	
282		var events []OutboxEvent
283	
284		switch work.kind {
285		case workForward:
286			step := &ex.Steps[work.index]
287			if step.State != StepPending {
288				return false, nil // 已被确认（成功或失败），重读决策。
289			}
290			step.Attempts++
291			if actionErr != nil {
292				step.State = StepFailed
293				step.LastError = actionErr.Error()
294				events = append(events, e.newEvent(ex, EventStepFailed, EventPayload{
295					Step: step.Name, State: ex.State, Reason: step.LastError, Attempts: step.Attempts,
296				}))
297				// 没有任何此前确认成功的步骤：无需补偿，立即形成 failed 终态。
298				if !anySucceeded(ex.Steps) {
299					ex.State = StateFailed
300					ex.FailureReason = forwardFailureReason(ex.Steps)
301					events = append(events, e.newEvent(ex, EventExecutionFailed, EventPayload{
302						State: StateFailed, Reason: ex.FailureReason,
303					}))
304				}
305				break
306			}
307			step.State = StepSucceeded
308			step.LastError = ""
309			events = append(events, e.newEvent(ex, EventStepSucceeded, EventPayload{
310				Step: step.Name, State: ex.State, Attempts: step.Attempts,
311			}))
312			// 正向全部确认：形成 completed 终态。
313			if allSucceeded(ex.Steps) {
314				ex.State = StateCompleted
315				events = append(events, e.newEvent(ex, EventExecutionCompleted, EventPayload{
316					State: StateCompleted,
317				}))
318			}
319	
320		case workCompensate:
321			step := &ex.Steps[work.index]
322			if step.State != StepSucceeded {
323				return false, nil // 补偿已被确认或执行已冻结，重读决策。
324			}
325			if actionErr != nil {
326				step.State = StepCompensationFailed
327				step.LastError = actionErr.Error()
328				ex.State = StateCompensationFailed
329				ex.FailureReason = fmt.Sprintf("compensation of step %q failed: %s", step.Name, actionErr.Error())
330				events = append(events, e.newEvent(ex, EventCompensationFailed, EventPayload{
331					Step: step.Name, State: StateCompensationFailed, Reason: ex.FailureReason,
332				}))
333				break
334			}
335			step.State = StepCompensated
336			step.LastError = ""
337			if def.Steps[work.index].Compensate != nil {
338				step.CompensationAttempts++
339			}
340			events = append(events, e.newEvent(ex, EventStepCompensated, EventPayload{
341				Step: step.Name, State: ex.State, Attempts: step.CompensationAttempts,
342			}))
343			// 逆序补偿全部完成：形成 failed 终态。
344			if !anySucceeded(ex.Steps) {
345				ex.State = StateFailed
346				ex.FailureReason = forwardFailureReason(ex.Steps)
347				events = append(events, e.newEvent(ex, EventExecutionFailed, EventPayload{
348					State: StateFailed, Reason: ex.FailureReason,
349				}))
350			}
351		}
352	
353		if err := tx.SaveExecution(ex, events); err != nil {
354			return false, err
355		}
356		if err := tx.Commit(); err != nil {
357			if err == ErrConcurrentUpdate {
358				return false, nil
359			}
360			return false, err
361		}
362		return true, nil
363	}
364	
365	// newEvent 追加一条事件：序号前移、ID 按执行身份与序号确定性生成。
366	func (e *Engine) newEvent(ex *Execution, typ EventType, p EventPayload) OutboxEvent {
367		ex.EventSeq++
368		payload, _ := json.Marshal(p)
369		return OutboxEvent{
370			ID:             fmt.Sprintf("%s:%s:%06d", ex.BusinessKey, ex.IdempotencyKey, ex.EventSeq),
371			BusinessKey:    ex.BusinessKey,
372			IdempotencyKey: ex.IdempotencyKey,
373			Type:           typ,
374			OccurredAt:     e.now().UTC(),
375			Payload:        payload,
376		}
377	}
378	
379	func allSucceeded(steps []StepRecord) bool {
380		for i := range steps {
381			if steps[i].State != StepSucceeded {
382				return false
383			}
384		}
385		return true
386	}
387	
388	func anySucceeded(steps []StepRecord) bool {
389		for i := range steps {
390			if steps[i].State == StepSucceeded {
391				return true
392			}
393		}
394		return false
395	}
396	
397	func forwardFailureReason(steps []StepRecord) string {
398		for i := range steps {
399			if steps[i].State == StepFailed {
400				return fmt.Sprintf("step %q failed: %s", steps[i].Name, steps[i].LastError)
401			}
402		}
403		return ""
404	}
405	
406	func buildResult(ex *Execution) Result {
407		r := Result{
408			BusinessKey:    ex.BusinessKey,
409			IdempotencyKey: ex.IdempotencyKey,
410			Saga:           ex.SagaName,
411			State:          ex.State,
412			FailureReason:  ex.FailureReason,
413			Steps:          make([]StepResult, len(ex.Steps)),
414		}
415		for i, s := range ex.Steps {
416			r.Steps[i] = StepResult{
417				Name:                 s.Name,
418				State:                s.State,
419				Attempts:             s.Attempts,
420				CompensationAttempts: s.CompensationAttempts,
421				Error:                s.LastError,
422			}
423		}
424		if r.State == StateFailed && r.FailureReason == "" {
425			r.FailureReason = forwardFailureReason(ex.Steps)
426		}
427		return r
428	}
